CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, nickname text NOT NULL DEFAULT 'عضو جديد' CHECK (char_length(nickname) BETWEEN 2 AND 40), birth_date date, city text NOT NULL DEFAULT '' CHECK (char_length(city)<=80), bio text NOT NULL DEFAULT '' CHECK (char_length(bio)<=1000), interests text[] NOT NULL DEFAULT '{}', discoverable boolean NOT NULL DEFAULT false, show_city boolean NOT NULL DEFAULT true, photo_visibility text NOT NULL DEFAULT 'private' CHECK (photo_visibility IN ('public','mutual','private')), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY profiles_own ON public.profiles FOR SELECT TO authenticated USING (id=auth.uid());
CREATE POLICY profiles_update ON public.profiles FOR UPDATE TO authenticated USING (id=auth.uid()) WITH CHECK (id=auth.uid());
CREATE FUNCTION public.validate_adult() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.birth_date IS NOT NULL AND (NEW.birth_date > (current_date - interval '18 years')::date OR NEW.birth_date < (current_date - interval '110 years')::date) THEN RAISE EXCEPTION 'يجب أن يكون عمرك 18 سنة أو أكثر'; END IF; IF NEW.discoverable AND NEW.birth_date IS NULL THEN RAISE EXCEPTION 'أكمل تاريخ ميلادك أولاً'; END IF; RETURN NEW; END $$;
CREATE TRIGGER validate_profile_adult BEFORE INSERT OR UPDATE ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.validate_adult();
CREATE FUNCTION public.create_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,nickname,birth_date) VALUES (NEW.id,coalesce(nullif(NEW.raw_user_meta_data->>'nickname',''),'عضو جديد'),nullif(NEW.raw_user_meta_data->>'birth_date','')::date); RETURN NEW; END $$;
CREATE TRIGGER create_tobezly_profile AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_profile();
CREATE TABLE public.user_roles(user_id uuid REFERENCES auth.users(id) ON DELETE CASCADE, role text NOT NULL CHECK(role IN ('admin','moderator')), PRIMARY KEY(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY roles_own ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.is_moderator() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND role IN ('admin','moderator')) $$;
REVOKE ALL ON FUNCTION public.is_moderator() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.is_moderator() TO authenticated;
CREATE TABLE public.blocks(user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, target_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, PRIMARY KEY(user_id,target_id), CHECK(user_id<>target_id));
GRANT SELECT, INSERT, DELETE ON public.blocks TO authenticated; GRANT ALL ON public.blocks TO service_role;
ALTER TABLE public.blocks ENABLE ROW LEVEL SECURITY;
CREATE POLICY blocks_own ON public.blocks FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TABLE public.likes(user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,target_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,PRIMARY KEY(user_id,target_id),CHECK(user_id<>target_id));
GRANT SELECT, INSERT, DELETE ON public.likes TO authenticated; GRANT ALL ON public.likes TO service_role;
ALTER TABLE public.likes ENABLE ROW LEVEL SECURITY;
CREATE POLICY likes_own ON public.likes FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE FUNCTION public.can_connect(other_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid() IS NOT NULL AND EXISTS(SELECT 1 FROM public.profiles WHERE id=auth.uid() AND birth_date IS NOT NULL) AND NOT EXISTS(SELECT 1 FROM public.blocks WHERE (user_id=auth.uid() AND target_id=other_id) OR (target_id=auth.uid() AND user_id=other_id)) $$;
REVOKE ALL ON FUNCTION public.can_connect(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.can_connect(uuid) TO authenticated;
CREATE FUNCTION public.is_mutual(other_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.can_connect(other_id) AND EXISTS(SELECT 1 FROM public.likes WHERE user_id=auth.uid() AND target_id=other_id) AND EXISTS(SELECT 1 FROM public.likes WHERE target_id=auth.uid() AND user_id=other_id) $$;
REVOKE ALL ON FUNCTION public.is_mutual(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.is_mutual(uuid) TO authenticated;
CREATE TABLE public.profile_photos(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,path text NOT NULL CHECK(char_length(path)<=300),status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected')),created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.profile_photos TO authenticated; GRANT ALL ON public.profile_photos TO service_role;
ALTER TABLE public.profile_photos ENABLE ROW LEVEL SECURITY;
CREATE POLICY photos_read ON public.profile_photos FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.is_moderator() OR (status='approved' AND public.can_connect(user_id) AND EXISTS(SELECT 1 FROM public.profiles p WHERE p.id=user_id AND p.discoverable AND (p.photo_visibility='public' OR (p.photo_visibility='mutual' AND public.is_mutual(p.id))))));
CREATE POLICY photos_add ON public.profile_photos FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND status='pending' AND path LIKE auth.uid()::text || '/%');
CREATE POLICY photos_delete ON public.profile_photos FOR DELETE TO authenticated USING(user_id=auth.uid());
CREATE POLICY photos_moderate ON public.profile_photos FOR UPDATE TO authenticated USING(public.is_moderator()) WITH CHECK(public.is_moderator());
CREATE TABLE public.reports(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES public.profiles(id),target_id uuid NOT NULL REFERENCES public.profiles(id),reason text NOT NULL CHECK(char_length(reason) BETWEEN 3 AND 1000),created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT ON public.reports TO authenticated; GRANT ALL ON public.reports TO service_role;
ALTER TABLE public.reports ENABLE ROW LEVEL SECURITY;
CREATE POLICY reports_add ON public.reports FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid());
CREATE POLICY reports_read ON public.reports FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.is_moderator());
CREATE FUNCTION public.discover_people() RETURNS TABLE(id uuid,nickname text,age integer,city text,bio text,interests text[],liked boolean,mutual boolean) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT p.id,p.nickname,extract(year FROM age(p.birth_date))::integer,CASE WHEN p.show_city THEN p.city ELSE '' END,p.bio,p.interests,EXISTS(SELECT 1 FROM public.likes WHERE user_id=auth.uid() AND target_id=p.id),public.is_mutual(p.id) FROM public.profiles p WHERE p.id<>auth.uid() AND p.discoverable AND p.birth_date IS NOT NULL AND public.can_connect(p.id) ORDER BY p.created_at DESC LIMIT 100 $$;
REVOKE ALL ON FUNCTION public.discover_people() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.discover_people() TO authenticated;
CREATE TABLE public.messages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),sender_id uuid NOT NULL REFERENCES public.profiles(id),recipient_id uuid NOT NULL REFERENCES public.profiles(id),body text NOT NULL CHECK(char_length(body) BETWEEN 1 AND 2000),created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT ON public.messages TO authenticated; GRANT ALL ON public.messages TO service_role;
ALTER TABLE public.messages ENABLE ROW LEVEL SECURITY;
CREATE POLICY messages_read ON public.messages FOR SELECT TO authenticated USING((sender_id=auth.uid() AND public.is_mutual(recipient_id)) OR (recipient_id=auth.uid() AND public.is_mutual(sender_id)));
CREATE POLICY messages_add ON public.messages FOR INSERT TO authenticated WITH CHECK(sender_id=auth.uid() AND public.is_mutual(recipient_id));
CREATE TABLE public.spaces(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_id uuid NOT NULL REFERENCES public.profiles(id),title text NOT NULL CHECK(char_length(title) BETWEEN 3 AND 100),city text NOT NULL CHECK(char_length(city) BETWEEN 2 AND 80),kind text NOT NULL CHECK(kind IN ('office','meeting','studio','home')),description text NOT NULL CHECK(char_length(description) BETWEEN 10 AND 2000),hourly_price integer NOT NULL CHECK(hourly_price>0),daily_price integer NOT NULL CHECK(daily_price>0),capacity integer NOT NULL DEFAULT 2 CHECK(capacity BETWEEN 1 AND 100),photos text[] NOT NULL DEFAULT '{}',published boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.spaces TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.spaces TO authenticated; GRANT ALL ON public.spaces TO service_role;
ALTER TABLE public.spaces ENABLE ROW LEVEL SECURITY;
CREATE POLICY spaces_public ON public.spaces FOR SELECT TO anon,authenticated USING(published);
CREATE POLICY spaces_own ON public.spaces FOR ALL TO authenticated USING(owner_id=auth.uid()) WITH CHECK(owner_id=auth.uid());
CREATE TABLE public.availability(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),space_id uuid NOT NULL REFERENCES public.spaces(id) ON DELETE CASCADE,starts_at timestamptz NOT NULL,ends_at timestamptz NOT NULL,CHECK(ends_at>starts_at));
GRANT SELECT ON public.availability TO anon; GRANT SELECT,INSERT,DELETE ON public.availability TO authenticated; GRANT ALL ON public.availability TO service_role;
ALTER TABLE public.availability ENABLE ROW LEVEL SECURITY;
CREATE POLICY slots_public ON public.availability FOR SELECT TO anon,authenticated USING(EXISTS(SELECT 1 FROM public.spaces WHERE id=space_id AND published));
CREATE POLICY slots_own ON public.availability FOR ALL TO authenticated USING(EXISTS(SELECT 1 FROM public.spaces WHERE id=space_id AND owner_id=auth.uid())) WITH CHECK(EXISTS(SELECT 1 FROM public.spaces WHERE id=space_id AND owner_id=auth.uid()));
CREATE TABLE public.bookings(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),space_id uuid NOT NULL REFERENCES public.spaces(id),guest_id uuid NOT NULL REFERENCES public.profiles(id),starts_at timestamptz NOT NULL,ends_at timestamptz NOT NULL,mode text NOT NULL CHECK(mode IN ('hour','day')),total integer NOT NULL CHECK(total>0),status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','accepted','rejected','cancelled')),created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.bookings TO authenticated; GRANT ALL ON public.bookings TO service_role;
ALTER TABLE public.bookings ENABLE ROW LEVEL SECURITY;
CREATE POLICY bookings_read ON public.bookings FOR SELECT TO authenticated USING(guest_id=auth.uid() OR EXISTS(SELECT 1 FROM public.spaces WHERE id=space_id AND owner_id=auth.uid()));
CREATE FUNCTION public.request_booking(_space_id uuid,_start timestamptz,_end timestamptz,_mode text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s public.spaces; amount integer; result uuid; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'سجل الدخول أولاً'; END IF; SELECT * INTO s FROM public.spaces WHERE id=_space_id AND published FOR UPDATE; IF NOT FOUND OR s.owner_id=auth.uid() THEN RAISE EXCEPTION 'لا يمكنك حجز هذا المكان'; END IF; IF _start<=now() OR _end<=_start OR _end-_start>interval '30 days' OR _mode NOT IN ('hour','day') THEN RAISE EXCEPTION 'وقت الحجز غير صالح'; END IF; IF _mode='day' AND _end-_start<>interval '24 hours' THEN RAISE EXCEPTION 'الحجز اليومي 24 ساعة'; END IF; IF NOT EXISTS(SELECT 1 FROM public.availability WHERE space_id=_space_id AND starts_at<=_start AND ends_at>=_end) THEN RAISE EXCEPTION 'الوقت المحدد غير متاح'; END IF; IF EXISTS(SELECT 1 FROM public.bookings WHERE space_id=_space_id AND status IN ('pending','accepted') AND starts_at<_end AND ends_at>_start) THEN RAISE EXCEPTION 'هذا الوقت محجوز بالفعل'; END IF; amount:=CASE WHEN _mode='day' THEN s.daily_price ELSE ceil(extract(epoch FROM (_end-_start))/3600)::integer*s.hourly_price END; INSERT INTO public.bookings(space_id,guest_id,starts_at,ends_at,mode,total) VALUES(_space_id,auth.uid(),_start,_end,_mode,amount) RETURNING id INTO result; RETURN result; END $$;
REVOKE ALL ON FUNCTION public.request_booking(uuid,timestamptz,timestamptz,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.request_booking(uuid,timestamptz,timestamptz,text) TO authenticated;
CREATE FUNCTION public.respond_booking(_id uuid,_status text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF _status='cancelled' THEN UPDATE public.bookings SET status=_status WHERE id=_id AND guest_id=auth.uid() AND status IN ('pending','accepted'); ELSIF _status IN ('accepted','rejected') THEN UPDATE public.bookings b SET status=_status WHERE b.id=_id AND b.status='pending' AND EXISTS(SELECT 1 FROM public.spaces s WHERE s.id=b.space_id AND s.owner_id=auth.uid()); ELSE RAISE EXCEPTION 'حالة غير صالحة'; END IF; IF NOT FOUND THEN RAISE EXCEPTION 'لا يمكن تعديل هذا الحجز'; END IF; END $$;
REVOKE ALL ON FUNCTION public.respond_booking(uuid,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.respond_booking(uuid,text) TO authenticated;
CREATE POLICY profile_storage_add ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='profile-photos' AND (storage.foldername(name))[1]=auth.uid()::text);
CREATE POLICY profile_storage_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='profile-photos' AND ((storage.foldername(name))[1]=auth.uid()::text OR public.is_moderator() OR EXISTS(SELECT 1 FROM public.profile_photos WHERE path=name AND status='approved')));
CREATE POLICY space_storage_add ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='space-photos' AND (storage.foldername(name))[1]=auth.uid()::text);
CREATE POLICY space_storage_read ON storage.objects FOR SELECT TO anon,authenticated USING(bucket_id='space-photos' AND ((storage.foldername(name))[1]=auth.uid()::text OR EXISTS(SELECT 1 FROM public.spaces WHERE published AND name=ANY(photos))));